import sys

def main():
    import sys
    import collections

    input = sys.stdin.read().split()
    index = 0
    n = int(input[index])
    m = int(input[index + 1])
    index += 2

    edges = collections.defaultdict(list)
    for _ in range(m):
        a = int(input[index]) - 1
        b = int(input[index + 1]) - 1
        edges[a].append(b)
        index += 2

    indegree = [0] * n
    for a in range(n):
        for b in edges[a]:
            indegree[b] += 1

    zero_indegree = [i for i in range(n) if indegree[i] == 0]
    one_move_reachable = set(zero_indegree)

    for a in zero_indegree:
        for b in edges[a]:
            one_move_reachable.add(b)

    two_move_reachable = set(one_move_reachable)
    for a in one_move_reachable:
        for b in edges[a]:
            two_move_reachable.add(b)

    result = []
    for i in range(n):
        if i not in two_move_reachable:
            result.append(i + 1)

    if not result:
        for i in range(n):
            if i not in one_move_reachable:
                result.append(i + 1)
                break

    print(len(result))
    print(" ".join(map(str, result)))

if __name__ == "__main__":
    main()
